+			: undefined;
+		this.markupPpm = config.markupPpm;
+		this.revenueSharePpm = config.revenueSharePpm;
+		this.maxTopUpUsd = config.maxTopUpUsd;
+		this.rpcClient = createPublicClient({
+			transport: http(config.rpcUrl),
+		});
+	}
