+		const result = await this.client
+			.wallets()
+			.ethereum()
+			.sendTransaction(this.getWalletId(), {
+				caip2: BASE_CAIP2,
+				params: {
+					transaction: {
+						to: this.splitAddress,
+						data,
+						value: 0,
+					},
+				},
